\set ON_ERROR_STOP on
begin;
create function pg_temp.ok(v boolean,m text) returns void language plpgsql as $$begin if not coalesce(v,false) then raise exception 'ASSERTION FAILED: %',m;end if;end$$;
create function pg_temp.expect(q text,m text) returns void language plpgsql as $$begin begin execute q;exception when others then if position(m in sqlerrm)>0 then return;end if;raise;end;raise exception 'Expected failure: %',m;end$$;
create function pg_temp.as_user(n integer) returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('sub','e4100000-0000-4000-8000-'||lpad(n::text,12,'0'),'role','authenticated')::text,true);end$$;
insert into public.tenants(id,slug,name) values('e4100000-0000-4000-8000-000000000100','hr10-a','HR10 A'),('e4100000-0000-4000-8000-000000000200','hr10-b','HR10 B');
insert into auth.users(id,aud,role,email,raw_user_meta_data) select ('e4100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'authenticated','authenticated','hr10-'||n||'@example.invalid','{}'::jsonb from generate_series(1,3)n;
update public.profiles set rol=(case right(id::text,1) when '2' then 'Ventas' else 'Admin' end)::public.user_role,status='Aprobado',is_active=true,is_platform_admin=false,tenant_id=case right(id::text,1) when '3' then 'e4100000-0000-4000-8000-000000000200'::uuid else 'e4100000-0000-4000-8000-000000000100'::uuid end where id::text like 'e4100000-%';
create temp table ids(name text primary key,id uuid);grant all on ids to authenticated;
create temp table data(input jsonb,snapshot jsonb,accounts jsonb,concepts jsonb);grant all on data to authenticated;
create function pg_temp.rows(a date,b date,worked boolean) returns jsonb language sql as $$select jsonb_build_array(jsonb_build_object('start',a,'end',b,'ordinary',180000,'in_kind',0,'extraordinary',case when worked then 18000 else 0 end,'worked_days',case when worked then 180 else 0 end,'source','Historial salarial sintetico comprobado'))$$;
set local role authenticated;select pg_temp.as_user(1);
select public.import_accounting_accounts('[{"code":"5101","name":"Prestaciones","kind":"Gasto"},{"code":"2101","name":"Prestaciones por pagar","kind":"Pasivo"}]');
select public.manage_accounting_period(date_trunc('year',current_date)::date,(date_trunc('year',current_date)+interval '1 year -1 day')::date);
insert into ids select 'employee',public.hr_save_employee(null,null,jsonb_build_object('employee_code','HR10','first_name','Persona','last_name','Sintética','hire_date',current_date-interval '16 years','contract_type','Indefinido','profile_id','e4100000-0000-4000-8000-000000000002'));
select public.hr_add_compensation((select id from ids where name='employee'),jsonb_build_object('effective_from',current_date-interval '16 years','currency','HNL','salary_mode','Fijo','monthly_salary',30000,'frequency','Mensual','source','Contrato sintetico confirmado para pruebas'));
insert into ids select 'concept',public.hr_save_payroll_concept(null,null,jsonb_build_object('code','PRESTACION','name','Prestaciones','kind','Ingreso','debit_account_id',(select id from public.accounting_accounts where code='5101')));
insert into data select jsonb_build_object('kind','Liquidación','as_of',current_date,'currency','HNL','regime','general_time','review_confirmed',true,'cause','despido_injustificado','microenterprise',false,'article120_excluded',false,'notice_served_days',0,'legal_source','Causal y protecciones revisadas con soporte sintetico','average_rows',pg_temp.rows((current_date+1-interval '6 months')::date,current_date,true),'bonus13_rows',pg_temp.rows(date_trunc('year',current_date)::date,current_date,false),'bonus14_rows',pg_temp.rows(make_date(extract(year from current_date)::int-case when extract(month from current_date)<7 then 1 else 0 end,7,1),current_date,false)),null,jsonb_build_object('pay_date',current_date,'payable_account_id',(select id from public.accounting_accounts where code='2101'),'exchange_rate',1),(select jsonb_object_agg(c,id) from unnest(array['vacation_balance','notice','severance','bonus13','bonus14','fixed_term'])c cross join ids where name='concept');
update data set snapshot=public.hr_preview_benefits((select id from ids where name='employee'),input);
select pg_temp.ok((select (snapshot->>'ordinary_daily')::numeric=35000.0/30 and (snapshot->>'indemnity_daily')::numeric=38000.0/30 from data),'ordinary integrates both bonuses; extraordinary only indemnity');
select pg_temp.ok((select (l->>'units')::numeric=60 from data,jsonb_array_elements(snapshot->'lines')l where l->>'component'='notice'),'over two years notice');
select pg_temp.ok((select (l->>'gross')::numeric=15000 from data,jsonb_array_elements(snapshot->'lines')l where l->>'component'='bonus13'),'annual ordinary earnings divided by twelve');
select pg_temp.ok((select (l->>'units')::numeric>168 and (l->>'units')::numeric<169 from data d cross join lateral jsonb_array_elements(public.hr_preview_benefits((select id from ids where name='employee'),input||'{"cause":"renuncia"}')->'lines')l where l->>'component'='severance'),'voluntary fifteen years receives 35 percent');
select pg_temp.ok((select (l->>'units')::numeric=0 from data cross join lateral jsonb_array_elements(public.hr_preview_benefits((select id from ids where name='employee'),input||'{"cause":"renuncia","microenterprise":true}')->'lines')l where l->>'component'='severance'),'micro does not use article120g');
select pg_temp.expect($$select public.hr_preview_benefits((select id from ids where name='employee'),input||'{"average_rows":[]}') from data$$,'Completa');
select pg_temp.expect($$select public.hr_preview_benefits((select id from ids where name='employee'),input||jsonb_build_object('average_rows',jsonb_set(input->'average_rows','{0,ordinary}','"NaN"'))) from data$$,'Revisa importes');
select pg_temp.expect($$select public.hr_preview_benefits((select id from ids where name='employee'),input||'{"regime":"piecework"}') from data$$,'Confirma');
select pg_temp.as_user(2);select pg_temp.expect($$select public.hr_preview_benefits((select id from ids where name='employee'),input) from data$$,'No autorizado');
select pg_temp.as_user(3);select pg_temp.expect($$select public.hr_preview_benefits((select id from ids where name='employee'),input) from data$$,'Empleado no disponible');select pg_temp.as_user(1);
insert into ids select 'credit',public.hr_record_benefit_credit('e410aaaa-0000-4000-8000-000000000001',(select id from ids where name='employee'),jsonb_build_object('component','bonus13','period_start',date_trunc('year',current_date)::date,'currency','HNL','amount',20000,'paid_on',current_date,'reference','RECIBO-SINTETICO-1','source','Pago previo externo sintetico revisado'));
select pg_temp.expect($$select public.hr_create_benefit_payroll(gen_random_uuid(),(select id from ids where name='employee'),input,snapshot->>'fingerprint',accounts,concepts) from data$$,'cambi');
update data set snapshot=public.hr_preview_benefits((select id from ids where name='employee'),input);
select pg_temp.ok((select (l->>'net')::numeric=0 and (l->>'excess_credit')::numeric=5000 from data,jsonb_array_elements(snapshot->'lines')l where l->>'component'='bonus13'),'excess credit does not deduct other benefits');
insert into ids select 'run',public.hr_create_benefit_payroll('e410aaaa-0000-4000-8000-000000000002',(select id from ids where name='employee'),input,snapshot->>'fingerprint',accounts,concepts) from data;
select pg_temp.ok((select public.hr_create_benefit_payroll('e410aaaa-0000-4000-8000-000000000002',(select id from ids where name='employee'),input,snapshot->>'fingerprint',accounts,concepts)=(select id from ids where name='run') from data),'idempotent generation');
select pg_temp.expect($$select public.hr_void_benefit_credit((select id from ids where name='credit'),'Anulacion sintetica documentada')$$,'nómina vigente');
select pg_temp.expect($$select public.hr_create_benefit_payroll(gen_random_uuid(),(select id from ids where name='employee'),input,snapshot->>'fingerprint',accounts,concepts) from data$$,'liquidación vigente');
select pg_temp.as_user(2);select pg_temp.ok((select count(*)=0 from public.hr_benefit_calculations),'own draft hidden');select pg_temp.as_user(1);
select public.hr_review_payroll((select id from ids where name='run'),'Aprobar','');
select pg_temp.as_user(2);select pg_temp.ok((select count(*)=1 from public.hr_benefit_calculations),'own approved detailed calculation visible');select pg_temp.ok((select count(*)=0 from public.hr_benefit_credits),'credit administration stays private');select pg_temp.as_user(3);select pg_temp.ok((select count(*)=0 from public.hr_benefit_calculations),'tenant boundary');select pg_temp.as_user(1);
insert into ids select 'journal',public.hr_review_payroll((select id from ids where name='run'),'Contabilizar','');
select pg_temp.ok((select sum(debit)=sum(credit) from public.journal_lines where entry_id=(select id from ids where name='journal')),'automatic benefits produce balanced journal');
select public.hr_review_payroll((select id from ids where name='run'),'Revertir','Reversion sintetica de prestaciones');
select public.hr_void_benefit_credit((select id from ids where name='credit'),'Anulacion de pago externo sintetico');
select pg_temp.as_user(2);select pg_temp.ok((select count(*)=0 from public.hr_benefit_calculations),'reversed report hidden from employee');select pg_temp.as_user(1);
update data set snapshot=public.hr_preview_benefits((select id from ids where name='employee'),input);
insert into ids select 'changed-run',public.hr_create_benefit_payroll(gen_random_uuid(),(select id from ids where name='employee'),input,snapshot->>'fingerprint',accounts,concepts) from data;
select public.hr_record_benefit_credit(gen_random_uuid(),(select id from ids where name='employee'),jsonb_build_object('component','bonus13','period_start',date_trunc('year',current_date)::date,'currency','HNL','amount',100,'paid_on',current_date,'reference','RECIBO-SINTETICO-2','source','Pago nuevo posterior al borrador sintetico'));
select pg_temp.expect($$select public.hr_review_payroll((select id from ids where name='changed-run'),'Aprobar','')$$,'cambi');
select pg_temp.ok((select status='Borrador' and journal_entry_id is null from public.hr_payroll_runs where id=(select id from ids where name='changed-run')),'stale calculation fails atomically');
select public.hr_review_payroll((select id from ids where name='changed-run'),'Anular','Recalculo sintetico despues de nuevo pago');
update data set snapshot=public.hr_preview_benefits((select id from ids where name='employee'),input);
insert into ids select 'post-stale',public.hr_create_benefit_payroll(gen_random_uuid(),(select id from ids where name='employee'),input,snapshot->>'fingerprint',accounts,concepts) from data;
select public.hr_review_payroll((select id from ids where name='post-stale'),'Aprobar','');
select public.hr_record_benefit_credit(gen_random_uuid(),(select id from ids where name='employee'),jsonb_build_object('component','bonus13','period_start',date_trunc('year',current_date)::date,'currency','HNL','amount',100,'paid_on',current_date,'reference','RECIBO-SINTETICO-3','source','Pago nuevo posterior a aprobacion sintetica'));
select pg_temp.expect($$select public.hr_review_payroll((select id from ids where name='post-stale'),'Contabilizar','')$$,'cambió');
select pg_temp.ok((select status='Aprobada' and journal_entry_id is null from public.hr_payroll_runs where id=(select id from ids where name='post-stale')),'stale posting rolls back the entire journal');
insert into ids select 'leave',public.hr_request_leave(gen_random_uuid(),(select id from ids where name='employee'),'Vacaciones',date_trunc('week',current_date)::date+14,date_trunc('week',current_date)::date+15,'Vacaciones sinteticas automaticas');
select public.hr_review_leave((select id from ids where name='leave'),'Aprobada','Aprobacion sintetica');
update data set input=input||jsonb_build_object('kind','Vacaciones','leave_request_id',(select id from ids where name='leave'));
update data set snapshot=public.hr_preview_benefits((select id from ids where name='employee'),input),concepts=concepts||jsonb_build_object('vacation',(select id from ids where name='concept'));
select pg_temp.ok((select jsonb_array_length(snapshot->'lines')=1 and (snapshot->'lines'->0->>'gross')::numeric=round(2*35000.0/30,2) from data),'approved vacation uses frozen workdays and ordinary integrated base');
insert into ids select 'vacation-run',public.hr_create_benefit_payroll(gen_random_uuid(),(select id from ids where name='employee'),input,snapshot->>'fingerprint',accounts,concepts) from data;
select public.hr_review_leave((select id from ids where name='leave'),'Cancelada','Cancelacion sintetica previa a pago');
select pg_temp.expect($$select public.hr_review_payroll((select id from ids where name='vacation-run'),'Aprobar','')$$,'vacaciones cambiaron');
insert into ids select 'cap-employee',public.hr_save_employee(null,null,jsonb_build_object('employee_code','HR10CAP','first_name','Tope','last_name','Sintético','hire_date',current_date-interval '30 years','contract_type','Indefinido'));
select public.hr_add_compensation((select id from ids where name='cap-employee'),jsonb_build_object('effective_from',current_date-interval '30 years','currency','HNL','salary_mode','Fijo','monthly_salary',30000,'frequency','Mensual','source','Contrato sintetico de larga antiguedad'));
do $$declare i jsonb;s jsonb;l jsonb;v uuid:=(select id from ids where name='cap-employee');begin
 select input||'{"kind":"Liquidación","leave_request_id":null}' into i from data;
 s:=public.hr_preview_benefits(v,i);select value into l from jsonb_array_elements(s->'lines') where value->>'component'='severance';perform pg_temp.ok((l->>'units')::numeric=750,'general cap 25 months');
 s:=public.hr_preview_benefits(v,i||'{"microenterprise":true}');select value into l from jsonb_array_elements(s->'lines') where value->>'component'='severance';perform pg_temp.ok((l->>'units')::numeric=450,'micro cap 15 months');
 s:=public.hr_preview_benefits(v,i||'{"article120_excluded":true}');select value into l from jsonb_array_elements(s->'lines') where value->>'component'='severance';perform pg_temp.ok((l->>'units')::numeric=0,'120f exclusion confirmed');
 s:=public.hr_preview_benefits(v,i||'{"cause":"fallecimiento_natural"}');select value into l from jsonb_array_elements(s->'lines') where value->>'component'='severance';perform pg_temp.ok((l->>'units')::numeric=562.5,'natural death seventy five percent');
 s:=public.hr_preview_benefits(v,i||'{"cause":"renuncia"}');select value into l from jsonb_array_elements(s->'lines') where value->>'component'='severance';perform pg_temp.ok((l->>'units')::numeric=262.5,'voluntary thirty five percent after cap');
 perform pg_temp.ok((public.hr_preview_benefits(v,i||'{"cause":"renuncia","favorable_proportional":true}')->>'vacation_partial_days')::numeric>(s->>'vacation_partial_days')::numeric,'favorable proportional policy explicit');
end$$;
insert into ids select 'currency-credit',public.hr_record_benefit_credit(gen_random_uuid(),(select id from ids where name='cap-employee'),jsonb_build_object('component','bonus13','period_start',date_trunc('year',current_date)::date,'currency','USD','amount',100,'paid_on',current_date,'reference','USD-SINTETICO','source','Pago en moneda distinta para conciliar'));
select pg_temp.expect($$select public.hr_preview_benefits((select id from ids where name='cap-employee'),input||'{"kind":"Liquidación","leave_request_id":null}') from data$$,'otra moneda');
select public.hr_void_benefit_credit((select id from ids where name='currency-credit'),'Conversion sintetica que requiere revision');
insert into ids select 'fixed-term',public.hr_save_employee(null,null,jsonb_build_object('employee_code','HR10PLAZO','first_name','Plazo','last_name','Sintético','hire_date',current_date-interval '2 years','contract_type','Temporal'));
select public.hr_add_compensation((select id from ids where name='fixed-term'),jsonb_build_object('effective_from',current_date-interval '2 years','currency','HNL','salary_mode','Fijo','monthly_salary',30000,'frequency','Mensual','source','Contrato temporal sintetico con fin comprobado'));
select pg_temp.expect($$select public.hr_preview_benefits((select id from ids where name='fixed-term'),input||'{"kind":"Liquidación","leave_request_id":null}') from data$$,'Art.121');
reset role;
do $$declare i jsonb;s jsonb;l jsonb;begin
 select input||jsonb_build_object('kind','Liquidación','leave_request_id',null,'contract_end',current_date+7) into i from data;
 s:=public.hr_preview_benefits((select id from ids where name='fixed-term'),i);
 select value into l from jsonb_array_elements(s->'lines') where value->>'component'='fixed_term';
 perform pg_temp.ok((l->>'gross')::numeric=round(30000.0*7/6/30*public.hr_labor_days(current_date+1,current_date+7),2),'fixed term uses documented remaining salary with indefinite cap');
end$$;
set local role authenticated;
select public.hr_add_compensation((select id from ids where name='fixed-term'),jsonb_build_object('effective_from',current_date+2,'currency','HNL','salary_mode','Fijo','monthly_salary',35000,'frequency','Mensual','source','Cambio salarial futuro sintetico documentado'));
select pg_temp.expect($$select public.hr_preview_benefits((select id from ids where name='fixed-term'),input||jsonb_build_object('kind','Liquidación','leave_request_id',null,'contract_end',current_date+7)) from data$$,'cambios salariales futuros');
reset role;
select pg_temp.ok(public.hr_labor_days('2025-01-01','2025-12-31')=360 and public.hr_labor_days('2024-02-29','2025-02-28')=361,'commercial inclusive date convention explicit');
rollback;
